export const useTools = (params: ToolsParams = {}) => {
  const { page = 1, limit = 10, ...rest } = params
  return useQuery<Tool[]>({
    queryKey: ['tools', { page, limit, ...rest }],
    queryFn: () => api.get('/tools', { _page: page, _limit: limit, ...rest }),
  })
}

export const useCreateTool = (onSuccess?: () => void) => {
  const qc = useQueryClient()
  return useMutation({
    mutationFn: (data: Partial<Tool>) => toolMutations.create(data),
    onSuccess: () => { qc.invalidateQueries({ queryKey: ['tools'] }); onSuccess?.() },
  })
}

